package com.lolfm.composition;
import com.lolfm.champion.ChampionRoleKey;import java.util.*;
public record ChampionCompositionProfile(ChampionRoleKey championRoleKey,Map<CompositionCapability,Integer> capabilities,DamageChannelProfile damageProfile){public ChampionCompositionProfile{Objects.requireNonNull(championRoleKey);Objects.requireNonNull(capabilities);Objects.requireNonNull(damageProfile);EnumMap<CompositionCapability,Integer>copy=new EnumMap<>(CompositionCapability.class);copy.putAll(capabilities);if(copy.size()!=CompositionCapability.values().length)throw new IllegalArgumentException("Exactly fifteen capabilities required");for(var c:CompositionCapability.values()){Integer v=copy.get(c);if(v==null||v<0||v>20)throw new IllegalArgumentException("Capability "+c+" must be 0..20");}capabilities=Map.copyOf(copy);}public int capability(CompositionCapability c){return capabilities.get(Objects.requireNonNull(c));}}
